
/* ===== وثيقة التخرج v12: تصميم بصري على نموذج الوثيقة الرسمية المرجعية — البيانات كما في النظام دون تغيير ===== */
(()=>{try{
const css=document.createElement('style');css.id='gd12css';
css.textContent=`.gd12{width:1123px;height:794px;position:relative;direction:rtl;color:#101a33;overflow:hidden;font-family:Amiri,'Noto Naskh Arabic',serif;background:#f6f8fb}
.gd12 *{box-sizing:border-box}
.gd12 .g-svg{position:absolute;left:0;top:0;width:1123px;height:794px}
.gd12 .g-wm{position:absolute;left:331px;top:196px;width:460px;height:460px;object-fit:contain;opacity:.085}
.gd12 .g-ln{position:absolute;inset:12px;border:1px solid #b4c6dc}
.gd12 .g-ln2{position:absolute;inset:16px;border:1px solid #d3e0ee}
.gd12 .g-bs{position:absolute;top:24px;left:0;right:0;text-align:center;font:700 23px/1.3 'Noto Naskh Arabic','Traditional Arabic',Amiri,serif;color:#1c3a6b}
.gd12 .g-hd{position:absolute;top:44px;right:64px;left:64px;height:118px;display:grid;grid-template-columns:1fr 150px 1fr;align-items:center}
.gd12 .g-ar{text-align:right;line-height:1.55;color:#101a33}
.gd12 .g-ar b{display:block;font:700 23px/1.6 'Noto Naskh Arabic','Traditional Arabic',Amiri,serif}
.gd12 .g-ar span{display:block;font:700 20px/1.65 'Noto Naskh Arabic','Traditional Arabic',Amiri,serif}
.gd12 .g-en{direction:ltr;text-align:left;line-height:1.45;color:#101a33;font-family:'Times New Roman',Times,serif}
.gd12 .g-en b{display:block;font-size:17px;font-weight:700}
.gd12 .g-en span{display:block;font-size:16.5px;font-weight:700}
.gd12 .g-hd img{height:108px;max-width:150px;object-fit:contain;display:block;margin:0 auto}
.gd12 .g-ti{position:absolute;top:168px;left:0;right:0;text-align:center;line-height:1.2}
.gd12 .g-ti b{display:block;font:700 27px/1.2 'Noto Naskh Arabic','Traditional Arabic',Amiri,serif;color:#101a33}
.gd12 .g-ti span{display:block;font:700 16px/1.3 'Times New Roman',Times,serif;color:#101a33}
.gd12 .g-bd{position:absolute;top:214px;right:60px;left:60px}
.gd12 .g-r{display:grid;grid-template-columns:1fr 1fr;gap:30px;align-items:center;min-height:29px;padding:1px 0}
.gd12 .g-r .a{text-align:right;font:700 16.5px/1.4 Amiri,'Noto Naskh Arabic',serif}
.gd12 .g-r .e{direction:ltr;text-align:left;font:700 15.5px/1.35 'Times New Roman',Times,serif}
.gd12 .g-r.nm{min-height:40px}
.gd12 .g-r.nm .a{font-size:20px}.gd12 .g-r.nm .e{font-size:18px;text-transform:uppercase}
.gd12 .g-ft{position:absolute;left:60px;right:60px;top:596px;height:140px}
.gd12 .g-qr{position:absolute;left:0;top:6px;width:84px;height:84px}
.gd12 .g-qr img{width:100%;height:100%;display:block}
.gd12 .g-idn{position:absolute;left:0;top:98px;font:700 13px/1.4 'Times New Roman',Times,serif;direction:ltr;color:#101a33}
.gd12 .g-dn{position:absolute;left:50%;margin-left:-190px;width:380px;top:0;text-align:center;line-height:1.35}
.gd12 .g-dn b{display:block;font:700 19px/1.4 Amiri,serif}
.gd12 .g-dn em{display:block;font:700 17px/1.3 'Times New Roman',Times,serif;font-style:normal;direction:ltr}
.gd12 .g-dn .im{height:50px;display:flex;justify-content:center;align-items:center;direction:ltr}
.gd12 .g-dn .im img.sig{height:48px;max-width:150px;object-fit:contain}
.gd12 .g-dn .nmz{font:700 18px/1.4 Amiri,serif}
.gd12 .g-dn .nme{font:700 16.5px/1.3 'Times New Roman',Times,serif;direction:ltr}
.gd12 .g-dn img.sl{position:absolute;left:-30px;top:40px;height:86px;max-width:94px;object-fit:contain;opacity:.92}
.gd12 .g-inf{position:absolute;right:0;top:0;width:290px;text-align:right;font:700 14.5px/1.5 Amiri,serif}
.gd12 .g-inf div{margin-bottom:4px}.gd12 .g-inf .en{direction:ltr;text-align:right;font:700 13.5px/1.4 'Times New Roman',Times,serif}
.gd12 .g-nt{position:absolute;left:60px;right:60px;top:744px;display:flex;justify-content:space-between;font-size:11.5px;line-height:1.4;color:#27324f}
.gd12 .g-nt .en{direction:ltr;font-family:'Times New Roman',Times,serif;font-weight:700}.gd12 .g-nt .ar{font-weight:700}
.gd12 .g-inf .au{margin-bottom:10px;text-align:center;width:170px;margin-right:0;margin-left:auto}.gd12 .g-inf .au span{display:block;font:700 13px/1.4 Amiri,serif;text-align:right}.gd12 .g-inf .au b{display:block;font:700 18px/1.5 Amiri,serif}.gd12 .g-inf .au i{display:block;height:1px;background:#101a33;margin:0 0 2px}.gd12 .g-inf .au em{display:block;font:700 12.5px/1.3 'Times New Roman',Times,serif;font-style:normal;direction:ltr}
.gd12 .g-r{border-bottom:1px solid rgba(42,92,158,.10)}
.gd12 .g-r.nm{background:linear-gradient(90deg,transparent,rgba(91,148,214,.16) 12%,rgba(91,148,214,.16) 88%,transparent);border-top:1.5px solid rgba(20,50,100,.35);border-bottom:1.5px solid rgba(20,50,100,.35);margin:3px 0;padding:3px 10px}
.gd12 .g-r.nm .a{color:#12356b}.gd12 .g-r.nm .e{color:#12356b}
.gd12 .g-ti b{font-size:30px;color:#12356b}.gd12 .g-ti span{letter-spacing:2px;color:#12356b}
.gd12 .g-dv{position:absolute;top:158px;left:64px;right:64px;height:10px}
.gd12 .g-mt{position:absolute;left:30px;right:30px;top:768px;height:9px;overflow:hidden;white-space:nowrap;font:600 6px/9px 'IBM Plex Sans Arabic',Arial,sans-serif;color:#3a5f93;opacity:.65;text-align:center;direction:rtl}
.gd12 .g-qr{padding:4px;background:#fff;border:1px solid #9fb6d3;box-shadow:0 1px 3px rgba(20,50,100,.12)}
.gd12 .g-dn i.ln{display:block;height:1px;width:250px;margin:0 auto 3px;background:linear-gradient(90deg,transparent,#12356b,transparent)}
.gd12 .g-rvk{position:absolute;top:290px;left:300px;z-index:5;transform:rotate(-20deg);font:700 110px/1.2 Amiri,serif;color:rgba(179,38,30,.35);border:8px solid rgba(179,38,30,.35);padding:0 30px;border-radius:14px}`;
document.head.appendChild(css);

window.__LG12=null;
try{const im=new Image();im.onload=()=>{try{const cv=document.createElement('canvas');cv.width=im.naturalWidth;cv.height=im.naturalHeight;const x=cv.getContext('2d');x.drawImage(im,0,0);const d=x.getImageData(0,0,cv.width,cv.height),p=d.data;for(let i=0;i<p.length;i+=4){const r=p[i],g=p[i+1],b=p[i+2],m=Math.min(r,g,b);if(m>225){p[i+3]=0;continue}if(m>170)p[i+3]=Math.min(p[i+3],(225-m)/55*255);const t=Math.min(1,(r*.3+g*.59+b*.11)/255*1.6);p[i]=26+60*t;p[i+1]=70+90*t;p[i+2]=135+85*t}x.putImageData(d,0,0);window.__LG12=cv.toDataURL('image/png')}catch(e){}};(window.requestIdleCallback||function(f){setTimeout(f,1500)})(function(){im.src=LOGO},{timeout:5000})}catch(e){}

/* خلفية: تدرج أزرق خفيف في الرأس + زخرفة هندسية + كتابة مائية متكررة بشفافية */
const AR='معهد التمهيد',EN='AT TAMHID INSTITUTE';
const lines=[];for(let i=0;i<9;i++){const y=262+i*36;lines.push(`<text direction="ltr" x="${i%2?-120:-20}" y="${y}" font-family="${i%2?"'Times New Roman',serif":'Amiri,serif'}" font-size="${i%2?21:25}" font-weight="700" fill="#5d7798">${(i%2?EN+'   ':AR+'   ').repeat(4)}</text>`)}
const SVG=`<svg class="g-svg" viewBox="0 0 1123 794"><defs>
<linearGradient id="g12h" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#cfe0f1"/><stop offset=".55" stop-color="#e2edf8"/><stop offset="1" stop-color="#f6f8fb"/></linearGradient>
<pattern id="g12p" width="72" height="72" patternUnits="userSpaceOnUse"><g fill="none" stroke="#fff" stroke-width="1.6" stroke-opacity=".7"><rect x="16" y="16" width="40" height="40"/><rect x="16" y="16" width="40" height="40" transform="rotate(45 36 36)"/><circle cx="36" cy="36" r="10"/></g><g fill="none" stroke="#6f95c2" stroke-width=".7" stroke-opacity=".55"><rect x="16" y="16" width="40" height="40"/><rect x="16" y="16" width="40" height="40" transform="rotate(45 36 36)"/></g></pattern>
<linearGradient id="g12m" x1="0" y1="0" x2="1" y2="0"><stop offset="0" stop-color="#fff"/><stop offset=".3" stop-color="#000"/><stop offset=".7" stop-color="#000"/><stop offset="1" stop-color="#fff"/></linearGradient>
<mask id="g12k"><rect width="1123" height="794" fill="url(#g12m)"/></mask>
<linearGradient id="g12f" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#fff" stop-opacity="0"/><stop offset="1" stop-color="#fff" stop-opacity=".9"/></linearGradient>
<mask id="g12v"><linearGradient id="g12vg" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#fff"/><stop offset=".25" stop-color="#fff"/><stop offset=".42" stop-color="#000"/></linearGradient><rect width="1123" height="794" fill="url(#g12vg)"/></mask></defs>
<rect width="1123" height="794" fill="url(#g12h)"/>
<rect width="1123" height="330" fill="url(#g12p)" opacity="1" mask="url(#g12v)"/>
<rect y="120" width="1123" height="674" fill="#f6f8fb" opacity="0"/>
<g mask="url(#g12k)" opacity=".22">${lines.join('')}</g></svg>`;

const CRN=[[22,22,1,1],[1101,22,-1,1],[22,772,1,-1],[1101,772,-1,-1]].map(([x,y,a,b])=>`<path d="M${x} ${y+b*34}V${y}H${x+a*34}" fill="none" stroke="#12356b" stroke-width="2.2"/><path d="M${x+a*6} ${y+b*40}V${y+b*6}H${x+a*40}" fill="none" stroke="#7aa6dc" stroke-width="1"/>`).join('');
const DIV=`<svg class="g-dv" viewBox="0 0 995 10" preserveAspectRatio="none"><defs><linearGradient id="g12d" x1="0" x2="1"><stop offset="0" stop-color="#12356b" stop-opacity="0"/><stop offset=".2" stop-color="#12356b" stop-opacity=".55"/><stop offset=".8" stop-color="#12356b" stop-opacity=".55"/><stop offset="1" stop-color="#12356b" stop-opacity="0"/></linearGradient></defs><rect x="0" y="4.5" width="995" height="1" fill="url(#g12d)"/><path d="M497.5 0l6 5-6 5-6-5z" fill="#12356b"/></svg>`;
const MT12='معهد التمهيد · AT TAMHID INSTITUTE · ';
const D=d=>{const[y,m,x]=String(d||'').split('-');return y&&m&&x?`${x}/${m}/${y}`:''},
hj=d=>{try{const p=new Intl.DateTimeFormat('en-u-ca-islamic-umalqura-nu-latn',{day:'2-digit',month:'2-digit',year:'numeric'}).formatToParts(new Date(d+'T12:00:00')),g=t=>(p.find(x=>x.type==t)||{}).value;return `${g('day')}-${g('month')}-${g('year')}`}catch(e){return ''}},
NAT={'سعودي':'Saudi','سعودية':'Saudi','بنغلاديشي':'Bangladeshi','بنجلاديشي':'Bangladeshi','البنغلاديشية':'Bangladeshi','البنجلاديشية':'Bangladeshi','هندي':'Indian','الهندية':'Indian','باكستاني':'Pakistani','الباكستانية':'Pakistani','مصري':'Egyptian','يمني':'Yemeni','إندونيسي':'Indonesian','اندونيسي':'Indonesian','نيجيري':'Nigerian','تركي':'Turkish','صومالي':'Somali','سوداني':'Sudanese','أفغاني':'Afghan','نيبالي':'Nepali','سريلانكي':'Sri Lankan'},
GR=g=>g>=4.5?['ممتاز','EXCELLENT']:g>=3.75?['جيد جداً','VERY GOOD']:g>=2.75?['جيد','GOOD']:g>=2?['مقبول','ACCEPTABLE']:['راسب','FAIL'],
ORD={'الأول':1,'الثاني':2,'الثالث':3,'الرابع':4};
const row=(a,e,k)=>`<div class="g-r ${k||''}"><div class="a">${a}</div><div class="e" dir="ltr">${e}</div></div>`,bd=x=>`<bdi dir="ltr">${esc(x)}</bdi>`;

window.gradHTML=c=>{
const st=S.students.find(x=>x.id==c.sid)||{},rq=S.requests.find(r=>r.sid==c.sid)||{},nEn=st.nameEn||rq.nameEn||c.nameEn||c.name,nat=c.nat||st.nat||'',natEn=NAT[nat]||st.natEn||rq.natEn||nat,
gpa=parseFloat(c.gpa),g=GR(isNaN(gpa)?0:gpa),lv=(m=>m?ORD[m[1]]:4)(/(الأول|الثاني|الثالث|الرابع)/.exec(c.gterm||'')),sem=lv%2?['الأول','FIRST']:['الثاني','SECOND'],
gd=c.gdate||c.date,y=+String(gd).slice(0,4),mo=+String(gd).slice(5,7),ay=mo>=8?y+'–'+(y+1):(y-1)+'–'+y,hg=hj(gd),hi=hj(c.date),LG=window.__LG12||LOGO;
let vu='';try{vu=vlink(c.rec)}catch(e){}
/* بيانات الوثيقة كما هي في النظام دون أي تغيير */
const body=row('يشهد معهد التمهيد بأن','At Tamhid Institute Certifies that')+
row(esc(c.name),esc(nEn),'nm')+
row(`الجنسية: ${esc(nat||'—')}`,`Nationality: ${esc(natEn||'—')}`)+
row(`رقم الهوية / الجواز: ${bd(c.pid||'—')}`,`ID / Passport No.: ${esc(c.pid||'—')}`)+row(`الرقم الأكاديمي: ${bd(c.sid||'—')}`,`Student ID: ${esc(c.sid||'—')}`)+
row('قد حصل على شهادة الدبلوم العام في اللغة العربية لغير الناطقين بها','Was Awarded The Diploma of General Arabic Language for Non-Native Speakers')+
row('مدة البرنامج: 80 ساعة معتمدة - 4 فصول دراسية','Program Duration: 80 Credit Hours - 4 Semesters')+
row('موزعة على عامين بواقع فصلين دراسيين في كل عام','Distributed over two years, two semesters per year')+
row(`بمعدل تراكمي ( ${bd(c.gpa)} من 5.00 ) وتقدير عام ${g[0]}`,`With a Cumulative GPA of ( ${esc(c.gpa)} / 5.00 ), ${g[1]}`)+
row(`في الفصل الدراسي ${sem[0]} للعام الدراسي ${bd(ay)}م`,`In the ${sem[1]} Semester, Academic Year ( ${esc(ay)} )`)+
row(`تم منح الدرجة بقرار مجلس إدارة المعهد رقم ( ${bd(c.boardNo)} ) في جلسته رقم ( ${bd(c.sessNo)} ) — تاريخ التخرج: ${bd(hg)} هـ الموافق ${bd(D(gd))} م`,`Approved by the Institute Board, Decision No. ( ${esc(c.boardNo)} ), Session No. ( ${esc(c.sessNo)} ) — Graduation Date: ${esc(D(gd))} AD (${esc(hg)} AH)`);
return `<div class="gd12">${c.revoked?'<div class="g-rvk">ملغاة</div>':''}${SVG}<img class="g-wm" src="${window.LOGOM||LG}" alt=""><div class="g-ln"></div><div class="g-ln2"></div><svg class="g-svg" viewBox="0 0 1123 794" style="pointer-events:none">${CRN}</svg>${DIV}<div class="g-mt">${MT12.repeat(10)}</div>
<div class="g-bs">بسم الله الرحمن الرحيم</div>
<div class="g-hd"><div class="g-ar"><b>معهد التمهيد</b><span>مجلس الشؤون التعليمية</span><span>عمادة القبول والتسجيل</span></div><img src="${LG}" alt=""><div class="g-en"><b>At Tamhid Institute</b><span>Board of Educational Affairs</span><span>Deanship of Admission &amp; Registration</span></div></div>
<div class="g-ti"><b>وثيقة تخرج</b><span>Graduation Certificate</span></div>
<div class="g-bd">${body}</div>
<div class="g-ft"><div class="g-qr"><img src="${qr(vu||c.rec)}" alt=""></div><div class="g-idn">Record No.: ${esc(c.rec)}</div>
<div class="g-dn"><b>رئيس معهد التمهيد</b><em>Chairman of At Tamhid Institute</em><div class="im"><img class="sig" src="${SIG}" alt=""></div><div class="nmz">أ. المفتي منير الإسلام بن معيذ الدين</div><div class="nme">Mufti Munirul Islam Ibn Moiez Uddin</div></div>
<div class="g-inf"><div class="au"><span>المدقق :</span><b>تدقيق إلكتروني</b><i></i></div><div>حُرّرت في ${bd(hi)} هـ الموافق ${bd(D(c.date))} م</div><div class="en">Issue Date: ${esc(D(c.date))} AD (${esc(hi)} AH)</div></div></div>
<div class="g-nt"><span class="en">ANY ADDITION, ALTERATION OR ERASURE VOIDS THIS DOCUMENT.</span><span class="ar">أي كشط أو تعديل يلغي هذه الوثيقة</span></div></div>`};
}catch(e){console.error('gd12',e)}})();
